, 1, 0, 2, '10e', '75', 2, 'EUR', 1, true, 'FR', 'CLEANING', NULL, 'CLENZY', 10, 'FLEXIBLE', 'everyone', false, false, false, true, 'Europe/Paris', 76.00, 175.00);
