SELECT id + 100000, channel, channel_guest_id, country_code, created_at, email, first_name, language, last_name, notes, :org_id, phone, total_spent, total_stays, updated_at, phone_hash, NULL FROM import_stage.guests;

SELECT id + 100000, access_notes, actual_cost, actual_duration_minutes, NULL, assigned_technician_id, NULL, completed_at, completed_steps, created_at, customer_feedback, customer_rating, description, end_time, estimated_cost, estimated_duration_hours, follow_up_notes, guest_checkin_time, guest_checkout_time, is_urgent, materials_used, notes, paid_at, payment_status, photos, preferred_time_slot, priority, progress_percentage, requires_follow_up, scheduled_date, special_instructions, start_time, status, NULL, NULL, team_id, technician_notes, title, type, updated_at, validated_rooms, NULL, property_id + 100000, :owner_id, NULL, :org_id, currency, version, recommended_cost, assignment_response, assignment_responded_at, assignment_decline_reason FROM import_stage.interventions;

SELECT id + 100000, check_in, check_in_time, check_out, check_out_time, confirmation_code, created_at, NULL, guest_count, guest_name, notes, source, source_name, status, total_price, updated_at, NULL, intervention_id + 100000, property_id + 100000, :org_id, guest_id + 100000, version, cleaning_fee, room_revenue, tax_amount, tourist_tax_amount, currency, payment_link_email, payment_link_sent_at, NULL, hidden_from_planning, paid_at, payment_status, service_options_total, original_total, discount_amount, voucher_code, NULL, ota_fee_amount, NULL, NULL, amount_paid, amount_due, balance_due_date, credit_applied, adults_count, children_count, NULL, cancelled_at, payment_collection, no_show, no_show_marked_at, no_show_marked_by FROM import_stage.reservations;

SELECT id + 100000, changeover_day, created_at, date, max_stay, min_stay, nightly_price, notes, :org_id, source, status, updated_at, property_id + 100000, reservation_id + 100000 FROM import_stage.calendar_days;

DROP SCHEMA import_stage CASCADE;

-- ── Sequences ─────────────────────────────────────────────────────────────
-- Sans cela, la prochaine creation depuis l'application reutiliserait un
-- identifiant deja pris par l'import.
SELECT setval(pg_get_serial_sequence('properties',    'id'), (SELECT max(id) FROM properties));
SELECT setval(pg_get_serial_sequence('guests',        'id'), (SELECT max(id) FROM guests));
SELECT setval(pg_get_serial_sequence('reservations',  'id'), (SELECT max(id) FROM reservations));
SELECT setval(pg_get_serial_sequence('interventions', 'id'), (SELECT max(id) FROM interventions));
SELECT setval(pg_get_serial_sequence('calendar_days', 'id'), (SELECT max(id) FROM calendar_days));

COMMIT;

\echo 'Import termine.'
